/* FinancialLibrary interactive tools (docs/resources/tools.md).
 *
 * Vanilla JS, no dependencies. Loaded site-wide via mkdocs.yml
 * extra_javascript, so every feature no-ops unless its elements exist.
 * Data comes from docs/assets/data/library-data.json, generated by
 * scripts/generate_interactive_data.py from data/kb-index.json — i.e. from
 * the curated records, never from values hard-coded here.
 */
(function () {
  "use strict";

  function dataUrl() {
    var el = document.querySelector("[data-fl-data-url]");
    return el ? el.getAttribute("data-fl-data-url") : null;
  }

  function loadData() {
    var url = dataUrl();
    if (!url || !window.fetch) return Promise.reject(new Error("no data url"));
    return fetch(url).then(function (resp) {
      if (!resp.ok) throw new Error("data fetch failed: " + resp.status);
      return resp.json();
    });
  }

  function pretty(code) {
    return String(code)
      .split("-")
      .map(function (w) {
        return w.charAt(0).toUpperCase() + w.slice(1);
      })
      .join(" ");
  }

  function fillSelect(select, values, allLabel) {
    var current = select.value;
    select.innerHTML = "";
    var all = document.createElement("option");
    all.value = "";
    all.textContent = allLabel;
    select.appendChild(all);
    values.forEach(function (v) {
      var opt = document.createElement("option");
      opt.value = v.value;
      opt.textContent = v.label;
      select.appendChild(opt);
    });
    select.value = current;
  }

  /* ---------------- Filterable catalog explorer ---------------- */

  function initCatalog(data) {
    var root = document.getElementById("fl-catalog");
    if (!root) return;
    var countrySel = document.getElementById("fl-filter-country");
    var topicSel = document.getElementById("fl-filter-topic");
    var audienceSel = document.getElementById("fl-filter-audience");
    var searchInput = document.getElementById("fl-filter-search");
    var tbody = document.getElementById("fl-catalog-body");
    var countLine = document.getElementById("fl-catalog-count");
    if (!countrySel || !tbody) return;

    fillSelect(
      countrySel,
      data.countries.map(function (c) {
        return {
          value: c.code,
          label: c.name + " (" + c.resource_count + ")",
        };
      }),
      "All countries"
    );
    fillSelect(
      topicSel,
      data.topics.map(function (t) {
        return { value: t, label: pretty(t) };
      }),
      "All topics"
    );
    fillSelect(
      audienceSel,
      data.audiences.map(function (a) {
        return { value: a, label: pretty(a) };
      }),
      "All audiences"
    );

    function render() {
      var country = countrySel.value;
      var topic = topicSel.value;
      var audience = audienceSel.value;
      var q = (searchInput.value || "").toLowerCase().trim();
      var rows = data.resources.filter(function (r) {
        if (country && r.country !== country) return false;
        if (topic && r.topics.indexOf(topic) === -1) return false;
        if (audience && r.audience.indexOf(audience) === -1) return false;
        if (
          q &&
          (r.title + " " + r.country_name + " " + r.topics.join(" "))
            .toLowerCase()
            .indexOf(q) === -1
        )
          return false;
        return true;
      });

      tbody.innerHTML = "";
      rows.forEach(function (r) {
        var tr = document.createElement("tr");
        var tdTitle = document.createElement("td");
        var a = document.createElement("a");
        a.href = r.url;
        a.textContent = r.title;
        tdTitle.appendChild(a);
        tr.appendChild(tdTitle);
        tr.appendChild(cell(r.country_name));
        tr.appendChild(cell(pretty(r.source_type)));
        tr.appendChild(cell(r.topics.map(pretty).join(", ")));
        tr.appendChild(cell(r.audience.map(pretty).join(", ")));
        tr.appendChild(cell(r.last_checked));
        tbody.appendChild(tr);
      });
      if (!rows.length) {
        var tr = document.createElement("tr");
        var td = document.createElement("td");
        td.colSpan = 6;
        td.textContent =
          "No records match these filters yet. Try widening them, or browse the full catalog.";
        tr.appendChild(td);
        tbody.appendChild(tr);
      }
      countLine.textContent =
        "Showing " + rows.length + " of " + data.resources.length + " records";
    }

    function cell(text) {
      var td = document.createElement("td");
      td.textContent = text;
      return td;
    }

    [countrySel, topicSel, audienceSel].forEach(function (el) {
      el.addEventListener("change", render);
    });
    searchInput.addEventListener("input", render);
    var reset = document.getElementById("fl-filter-reset");
    if (reset) {
      reset.addEventListener("click", function () {
        countrySel.value = "";
        topicSel.value = "";
        audienceSel.value = "";
        searchInput.value = "";
        render();
      });
    }
    render();
  }

  /* ---------------- Deposit-insurance lookup ---------------- */

  function initDepositInsurance(data) {
    var select = document.getElementById("fl-di-country");
    var result = document.getElementById("fl-di-result");
    if (!select || !result) return;

    fillSelect(
      select,
      data.countries
        .filter(function (c) {
          return c.code !== "global";
        })
        .map(function (c) {
          return { value: c.code, label: c.name };
        }),
      "Choose a country…"
    );

    select.addEventListener("change", function () {
      var code = select.value;
      result.innerHTML = "";
      if (!code) return;
      var name = select.options[select.selectedIndex].textContent;
      var entries = data.deposit_insurance.filter(function (d) {
        return d.country === code;
      });
      if (!entries.length) {
        var p = document.createElement("p");
        p.innerHTML =
          "<strong>Not in the library yet.</strong> FinancialLibrary does " +
          "not yet hold an official deposit-insurance source for " +
          name +
          ". That is a coverage gap in the library, not a statement about " +
          "the country — most countries do have a scheme. See " +
          '<a href="../../about/where-to-check/">Where to check official figures</a> ' +
          "for how to find the official source.";
        result.appendChild(p);
        return;
      }
      entries.forEach(function (d) {
        var p = document.createElement("p");
        var a = document.createElement("a");
        a.href = d.url;
        a.textContent = d.insurer;
        p.appendChild(document.createTextNode("Official source in the library: "));
        p.appendChild(a);
        p.appendChild(
          document.createTextNode(" (record checked " + d.last_checked + ").")
        );
        result.appendChild(p);
      });
      var note = document.createElement("p");
      note.textContent = data.deposit_insurance_note;
      result.appendChild(note);
    });
  }

  /* ---------------- Emergency-fund target calculator ----------------
   * Pure arithmetic on the visitor's own inputs (monthly essential
   * expenses x months of cover). An illustration for planning, not advice;
   * no figures come from the records or from defaults baked in here. */

  function initEmergencyFund() {
    var form = document.getElementById("fl-ef-form");
    if (!form) return;
    var expenses = document.getElementById("fl-ef-expenses");
    var months = document.getElementById("fl-ef-months");
    var monthsLabel = document.getElementById("fl-ef-months-label");
    var output = document.getElementById("fl-ef-result");

    function fmt(n) {
      return new Intl.NumberFormat(undefined, {
        maximumFractionDigits: 0,
      }).format(n);
    }

    function compute() {
      var m = parseInt(months.value, 10);
      monthsLabel.textContent = m + (m === 1 ? " month" : " months");
      var e = parseFloat(expenses.value);
      if (!expenses.value || isNaN(e) || e < 0) {
        output.textContent =
          "Enter your monthly essential expenses to see the target.";
        return;
      }
      output.textContent =
        "Target emergency fund: " +
        fmt(e * m) +
        " — that is " +
        m +
        " × " +
        fmt(e) +
        " of monthly essential expenses, in your own currency. " +
        "Illustration only, not advice: what counts as essential, and how " +
        "many months of cover fit your household, is your call.";
    }

    form.addEventListener("input", compute);
    form.addEventListener("submit", function (ev) {
      ev.preventDefault();
      compute();
    });
    compute();
  }

  function init() {
    initEmergencyFund();
    loadData()
      .then(function (data) {
        initCatalog(data);
        initDepositInsurance(data);
      })
      .catch(function () {
        var count = document.getElementById("fl-catalog-count");
        if (count) {
          count.textContent =
            "The interactive list could not load its data file. Please use the static catalog instead.";
        }
      });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
